#[cfg_attr(docsrs, doc(cfg(feature = "napi")))]
pub mod napi;
/// Pipeline step definitions and run state.
pub mod pipeline;
/// Structured recovery hints (`recovery[]`).
pub mod recovery;
/// Best-effort redaction of known secrets and URL userinfo.
